export type NetLearningStatus = 'not_started' | 'learning' | 'completed';
export type NetUnderstandingLevel = 'surface' | 'solid' | 'deep';

export interface NetModuleMeta {
  id: string;
  code: string; // '01'..'14'
  title: string;
  description: string;
  accent: string;
}

export interface NetDiagramBox {
  id: string;
  x: number;
  y: number;
  w: number;
  h: number;
  label: string;
  sub?: string;
  accent?: string;
}

export interface NetDiagramArrow {
  fromX: number;
  fromY: number;
  toX: number;
  toY: number;
  label?: string;
}

export interface CrossSystemLink {
  discipline: 'Operating Systems' | 'Computer Networking' | 'Backend Engineering' | 'Distributed Systems';
  targetLabel: string;
  reason: string;
  osTopicId?: string;
  netTopicId?: string;
}

export interface NetTopic {
  id: string;
  moduleId: string;
  code: string; // e.g. '06.03'
  title: string;
  subtitle: string;
  status: NetLearningStatus;
  understanding: NetUnderstandingLevel;
  bookmarked: boolean;
  weakFlag: boolean;
  tags: string[];
  relatedTopicIds: string[];
  crossSystemLinks: CrossSystemLink[];
  updatedAt: number;

  // 16 Structured Knowledge Components
  overview: string;
  coreConcepts: string[];
  definitions: { term: string; meaning: string }[];
  detailedTheory: string;
  howItWorks: string[];
  protocolSpecs: {
    rfcOrStandard: string;
    layer: string;
    portsOrProto: string;
    keyFields: string;
  };
  diagram: {
    title: string;
    boxes: NetDiagramBox[];
    arrows: NetDiagramArrow[];
  };
  packetAnalysis: {
    frameSummary: string;
    layers: { layerName: string; detail: string }[];
  };
  codeAndCommands: {
    language: string;
    title: string;
    snippet: string;
  };
  comparisons: { aspect: string; optionA: string; optionB: string }[];
  realWorldApplications: string[];
  troubleshooting: string[];
  securityConsiderations: string[];
  interviewQuestions: { question: string; answer: string }[];
  exercises: { id: string; prompt: string; solutionHint: string; done: boolean }[];
  references: { label: string; source: string; url?: string }[];
}

export interface NetComparisonMatrix {
  id: string;
  title: string;
  columns: string[];
  rows: { criterion: string; items: string[] }[];
}

export interface NetCommandRef {
  id: string;
  command: string;
  category: 'Diagnostics' | 'Routing & Interfaces' | 'Sockets & Ports' | 'DNS' | 'Packet Capture' | 'HTTP / TLS';
  purpose: string;
  examples: string[];
  keyFlags: string;
}

export interface NetPacketTraceSample {
  id: string;
  title: string;
  protocol: string;
  description: string;
  packets: {
    no: number;
    time: string;
    src: string;
    dst: string;
    proto: string;
    length: number;
    info: string;
    decodedLayers: string[];
  }[];
}

export interface NetTopologyNode {
  id: string;
  kind: 'Client' | 'Router' | 'Switch' | 'Firewall' | 'LoadBalancer' | 'Server';
  label: string;
  ip: string;
  x: number;
  y: number;
}

export interface NetTopologyEdge {
  id: string;
  fromId: string;
  toId: string;
  bandwidth: string;
  latencyMs: number;
}

export interface NetFlashcard {
  id: string;
  topicId: string;
  front: string;
  back: string;
  confidence: 'learning' | 'mastered';
  createdAt: number;
}

export interface NetResearchNote {
  id: string;
  topicId?: string;
  title: string;
  question: string;
  content: string;
  tags: string[];
  createdAt: number;
  updatedAt: number;
}

export interface NetRevisionEntry {
  id: string;
  topicId: string;
  dateStr: string;
  timestamp: number;
  note: string;
  statusAfter: NetLearningStatus;
}

export interface NetKnowledgeBaseState {
  activeTab:
    | 'dashboard'
    | 'curriculum'
    | 'packets_cli'
    | 'topology'
    | 'comparisons'
    | 'flashcards'
    | 'notes';
  activeModuleId: string;
  activeTopicId: string;
  topics: NetTopic[];
  topologyNodes: NetTopologyNode[];
  topologyEdges: NetTopologyEdge[];
  flashcards: NetFlashcard[];
  researchNotes: NetResearchNote[];
  revisionLogs: NetRevisionEntry[];
}

