export const NET_COMMAND_LIBRARY: NetCommandRef[] = [
  {
    id: 'cmd_ping',
    command: 'ping',
    category: 'Diagnostics',
    purpose: 'Kiểm tra khả năng kết nối IP lớp L3, đo RTT min/avg/max và tỷ lệ Packet Loss qua ICMP Echo.',
    examples: ['ping -c 4 1.1.1.1', 'ping -M do -s 1472 8.8.8.8  # Kiểm tra Path MTU 1500B'],
    keyFlags: '-c count · -i interval · -s payload_size · -M do (Don’t Fragment)',
  },
  {
    id: 'cmd_trace',
    command: 'traceroute / mtr',
    category: 'Diagnostics',
    purpose: 'Truy vết từng hop Router trên đường đi từ nguồn tới đích dựa vào việc tăng dần TTL (ICMP Time Exceeded).',
    examples: ['traceroute -n api.github.com', 'mtr --report -c 20 8.8.8.8'],
    keyFlags: '-n (không phân giải DNS cho nhanh) · -T (dùng TCP SYN thay UDP)',
  },
  {
    id: 'cmd_ip',
    command: 'ip addr / ip route',
    category: 'Routing & Interfaces',
    purpose: 'Xem/cấu hình địa chỉ IP, subnet CIDR, MAC address và bảng định tuyến Kernel trên Linux.',
    examples: ['ip -br addr show', 'ip route get 8.8.8.8', 'ip neigh show  # Xem ARP Cache'],
    keyFlags: 'ip a · ip r · ip neigh (thay thế ifconfig/route/arp cũ)',
  },
  {
    id: 'cmd_ss',
    command: 'ss / netstat',
    category: 'Sockets & Ports',
    purpose: 'Liệt kê mọi Socket TCP/UDP đang LISTEN hoặc ESTABLISHED/TIME_WAIT và tiến trình sở hữu.',
    examples: ['ss -tulnp', 'ss -s  # Thống kê tổng TCP states'],
    keyFlags: '-t (TCP) -u (UDP) -l (Listening) -n (Numeric port) -p (Process PID)',
  },
  {
    id: 'cmd_dig',
    command: 'dig / nslookup',
    category: 'DNS',
    purpose: 'Truy vấn bản ghi DNS (A, AAAA, CNAME, MX, TXT, NS) và kiểm tra thời gian phân giải + TTL.',
    examples: ['dig +trace example.com', 'dig @1.1.1.1 api.example.com A +short'],
    keyFlags: '+trace (dò từ Root -> TLD -> Authoritative) · +short',
  },
  {
    id: 'cmd_tcpdump',
    command: 'tcpdump',
    category: 'Packet Capture',
    purpose: 'Bắt và phân tích gói tin trực tiếp trên giao diện mạng bằng BPF filter.',
    examples: ['sudo tcpdump -ni eth0 port 443', 'sudo tcpdump -i any -w capture.pcap tcp port 8080'],
    keyFlags: '-n (no DNS) · -i any · -w file.pcap · -A (in ASCII)',
  },
  {
    id: 'cmd_curl',
    command: 'curl -v / openssl s_client',
    category: 'HTTP / TLS',
    purpose: 'Gỡ lỗi chi tiết DNS resolve time, TCP connect, TLS 1.3 handshake, chứng chỉ X.509 và HTTP headers.',
    examples: [
      'curl -vI https://example.com',
      'openssl s_client -connect example.com:443 -servername example.com',
    ],
    keyFlags: '-v (verbose handshake) · -I (HEAD only) · -w "%{time_connect} %{time_starttransfer}"',
  },
];

