interface NetTopicSeed {
  id: string;
  moduleId: string;
  code: string;
  title: string;
  subtitle: string;
  tags: string[];
  relatedTopicIds: string[];
  crossSystemLinks?: CrossSystemLink[];
  overview: string;
  coreConcepts: string[];
  definitions: { term: string; meaning: string }[];
  detailedTheory: string;
  howItWorks: string[];
  protocolSpecs: {
    rfcOrStandard: string;
    layer: string;
    portsOrProto: string;
    keyFields: string;
  };
  diagram: {
    title: string;
    boxes: NetDiagramBox[];
    arrows: NetDiagramArrow[];
  };
  packetAnalysis: {
    frameSummary: string;
    layers: { layerName: string; detail: string }[];
  };
  codeAndCommands: {
    language: string;
    title: string;
    snippet: string;
  };
  comparisons: { aspect: string; optionA: string; optionB: string }[];
  realWorldApplications: string[];
  troubleshooting: string[];
  securityConsiderations: string[];
  interviewQuestions: { question: string; answer: string }[];
  exercises: { id: string; prompt: string; solutionHint: string }[];
}

function defaultNetDiagram(title: string, a: string, b: string, c: string) {
  return {
    title,
    boxes: [
      { id: 'nb1', x: 30, y: 55, w: 175, h: 66, label: a, sub: 'Sender / Client', accent: '#A7B6D2' },
      { id: 'nb2', x: 255, y: 55, w: 195, h: 66, label: b, sub: 'Network Path / Protocol', accent: '#B99B79' },
      { id: 'nb3', x: 500, y: 55, w: 175, h: 66, label: c, sub: 'Receiver / Server', accent: '#9BAA98' },
    ],
    arrows: [
      { fromX: 205, fromY: 88, toX: 255, toY: 88, label: 'packet' },
      { fromX: 450, fromY: 88, toX: 500, toY: 88, label: 'deliver' },
    ],
  };
}

function makeNetTopic(seed: NetTopicSeed): NetTopic {
  return {
    ...seed,
    status: 'not_started',
    understanding: 'surface',
    bookmarked: false,
    weakFlag: false,
    crossSystemLinks: seed.crossSystemLinks || [
      {
        discipline: 'Backend Engineering',
        targetLabel: 'API Reliability & Timeout Budgets',
        reason: 'Hiểu tầng mạng giúp cấu hình retry, timeout và circuit breaker chính xác.',
      },
    ],
    updatedAt: Date.now() - 86400000,
    exercises: seed.exercises.map((e) => ({ ...e, done: false })),
    references: [
      {
        label: 'Computer Networking: A Top-Down Approach (8th Ed.)',
        source: 'Kurose & Ross',
        url: 'https://gaia.cs.umass.edu/kurose_ross/index.php',
      },
      {
        label: 'TCP/IP Illustrated, Vol. 1',
        source: 'W. Richard Stevens',
      },
    ],
  };
}

// Helper for concise yet authentic topic builders for standard topics while flagship topics carry deep full detail
function buildModuleTopics(
  moduleId: string,
  moduleNum: string,
  specs: Array<{
    sub: string;
    title: string;
    subtitle: string;
    tags: string[];
    related: string[];
    cross?: CrossSystemLink[];
    overview: string;
    concepts: string[];
    defs: { term: string; meaning: string }[];
    theory: string;
    steps: string[];
    rfc: string;
    layer: string;
    ports: string;
    fields: string;
    diag: [string, string, string, string];
    pktSummary: string;
    pktLayers: { layerName: string; detail: string }[];
    cmdLang: string;
    cmdTitle: string;
    cmd: string;
    cmp: { aspect: string; optionA: string; optionB: string }[];
    apps: string[];
    troubleshoot: string[];
    sec: string[];
    qa: { question: string; answer: string }[];
    ex: { prompt: string; solutionHint: string };
  }>
): NetTopicSeed[] {
  return specs.map((s, idx) => ({
    id: `net_${moduleNum}_${s.sub}`,
    moduleId,
    code: `${moduleNum}.${s.sub}`,
    title: s.title,
    subtitle: s.subtitle,
    tags: s.tags,
    relatedTopicIds: s.related,
    crossSystemLinks: s.cross,
    overview: s.overview,
    coreConcepts: s.concepts,
    definitions: s.defs,
    detailedTheory: s.theory,
    howItWorks: s.steps,
    protocolSpecs: {
      rfcOrStandard: s.rfc,
      layer: s.layer,
      portsOrProto: s.ports,
      keyFields: s.fields,
    },
    diagram: defaultNetDiagram(...s.diag),
    packetAnalysis: {
      frameSummary: s.pktSummary,
      layers: s.pktLayers,
    },
    codeAndCommands: {
      language: s.cmdLang,
      title: s.cmdTitle,
      snippet: s.cmd,
    },
    comparisons: s.cmp,
    realWorldApplications: s.apps,
    troubleshooting: s.troubleshoot,
    securityConsiderations: s.sec,
    interviewQuestions: s.qa,
    exercises: [{ id: `netex_${moduleNum}_${idx + 1}`, ...s.ex }],
  }));
}

