      theory: '### Tính toán Payload Efficiency\n- Ethernet Payload max (MTU) = **1500 bytes**.\n- Trừ IPv4 Header (20B) & TCP Header (20B) → **MSS = 1460 bytes**.\n- Nếu bạn gửi JSON nhỏ 10 bytes trên TCP/IP, tổng khung trên dây là $10 + 20 + 20 + 18 = 68$ bytes (**overhead > 85%**)! Đó là lý do Nagle’s algorithm hoặc batching rất quan trọng.',
