      concepts: ['Self-Learning MAC Table (CAM Table)', '3 Actions: Forward, Flood (Unknown/Broadcast), Filter', 'Switching Loop & Broadcast Storm (Không có TTL ở L2!)', 'Spanning Tree Protocol (STP / RSTP)'],
      defs: [{ term: 'Broadcast Storm', meaning: 'Vì Ethernet Frame ở Layer 2 KHÔNG có trường TTL như IP, nếu nối Switch thành vòng tròn, một gói ARP Broadcast sẽ xoay vòng nhân bản theo cấp số nhân làm tê liệt toàn mạng trong vài mili-giây!' }],
      theory: '### Thuật toán tự học của Switch\n1. Nhận frame từ cổng `P` với `SrcMAC = A`, `DstMAC = B`.\n2. **Học (Learn)**: Ghi `(A -> P, TTL=300s)` vào CAM Table.\n3. **Tra cứu (Lookup)** `B` trong bảng:\n   - Nếu `B` ở cùng cổng `P` → **Filter/Drop**.\n   - Nếu `B` ở cổng `Q != P` → **Forward** duy nhất ra cổng `Q`.\n   - Nếu chưa biết `B` hoặc `B` là `ff:ff:ff:ff:ff:ff` → **Flood** ra tất cả các cổng trừ `P`.',
