      theory: '### Tại sao một Web Server cổng 443 nhận được hàng vạn Client cùng lúc không bị giới hạn 65.535?\nSố 65.535 là số cổng tối đa **trên mỗi Client IP tới cùng 1 Server IP:Port** (vì Client chỉ chọn được từ dải Ephemeral Port). Nhưng trên phía Server, mỗi Client có `SrcIP` khác nhau nên bộ 4-tuple `(ClientIP, ClientPort, ServerIP, 443)` cho phép hàng triệu kết nối đồng thời (chỉ bị giới hạn bởi RAM & File Descriptors!).',
      steps: ['Server gọi `bind(port)` đăng ký với Transport Layer.', 'Gói tới OS kiểm tra cặp `(DstIP, DstPort)` + `(SrcIP, SrcPort)`.', 'Đẩy payload vào Receive Buffer của Socket khớp nhất.'],
