      sec: ['Quét cổng (`nmap`) dò tìm các dịch vụ mở không cần thiết; nguyên tắc là đóng hết mọi cổng trừ cổng cần thiết ở Firewall.'],
      qa: [{ question: 'Một máy chủ Nginx lắng nghe cổng 80/443 có bị giới hạn tối đa 65.535 kết nối đồng thời không?', answer: 'Không! 65.535 chỉ là giới hạn số Ephemeral Port từ một Client IP đơn lẻ tới cùng một đích; Server phân biệt kết nối bằng bộ 4-tuple `(SrcIP, SrcPort, DstIP, DstPort)` nên hỗ trợ hàng trăm nghìn tới hàng triệu kết nối từ nhiều Client IP khác nhau.' }],
