      theory: '### Tại sao WebRTC, Game Online và HTTP/3 (QUIC) lại chọn UDP?\n- Trong gọi video hay game FPS, **gói tin đến trễ 500ms còn vô dụng hơn là mất luôn gói đó**! TCP ép cả luồng phải khựng lại chờ truyền lại gói cũ (**Head-of-Line Blocking**).\n- UDP cho phép app tự quyết định: dữ liệu âm thanh mất thì bỏ qua đi tiếp, còn với QUIC/HTTP3 thì app tự cài đặt cơ chế tin cậy thông minh ngay trên UDP ở User Space.',
      steps: ['Đặt 8B UDP Header.', 'Tính Checksum (tùy chọn trên IPv4, BẮT BUỘC trên IPv6).', 'Đẩy thẳng xuống IP không cần chờ bắt tay.'],
