      sec: ['**UDP Reflection/Amplification DDoS**: Vì không cần bắt tay 3 bước, kẻ tấn công dễ dàng giả Src IP của nạn nhân gửi request nhỏ 60B tới server DNS/NTP/Memcached mở, ép server bắn response nhiều KB dội ngược vào nạn nhân!'],
