      cmp: [{ aspect: 'Ý nghĩa lỗi Production', optionA: 'Nhiều `TIME_WAIT`: Do đóng/mở kết nối liên tục (thiếu Keep-Alive/Pool)', optionB: 'Nhiều `CLOSE_WAIT`: BUG CODE! Bên kia đã đóng nhưng App mình quên gọi `socket.close()`' }],
      apps: ['Lý do dùng **HTTP Keep-Alive** và **Database Connection Pool** (HikariCP, PgBouncer): không phải trả 1 RTT TCP + 1–2 RTT TLS cho từng query nhỏ!'],
      troubleshoot: ['Thấy hàng nghìn socket kẹt ở **`CLOSE_WAIT`** trên server Java/Go/Node → chắc chắn code ứng dụng bị leak kết nối (không đóng HTTP client response body hoặc DB connection trong khối `finally`).'],
      sec: ['**SYN Flood DDoS**: Kẻ tấn công spam hàng triệu gói `SYN` với Src IP giả mà không gửi `ACK` bước 3 làm tràn SYN Queue → Kernel Linux chống bằng **SYN Cookies** (`net.ipv4.tcp_syncookies = 1`) không lưu trạng thái cho tới khi nhận được `ACK` hợp lệ!'],
      qa: [{ question: 'Trạng thái `TIME_WAIT` và `CLOSE_WAIT` khác nhau thế nào khi debug một Backend Server?', answer: '`TIME_WAIT` xảy ra ở bên CHỦ ĐỘNG đóng kết nối để đợi gói trễ và bảo vệ ACK cuối (hiện tượng bình thường, chỉ cần bật Keep-Alive/Connection Pool nếu quá nhiều); còn `CLOSE_WAIT` nhiều nghĩa là bên kia đã gửi FIN nhưng code ứng dụng cục bộ bị lỗi quên gọi `close()` giải phóng socket.' }],
      ex: { prompt: 'Chạy `ss -tan` trên máy bạn để xem có những kết nối nào đang ở `LISTEN`, `ESTAB` và `TIME-WAIT`.', solutionHint: 'Quan sát cột `State`, `Local Address:Port` và `Peer Address:Port`.' },
