      cmd: 'sysctl net.ipv4.tcp_congestion_control\n# Bật BBR: sudo sysctl -w net.core.default_qdisc=fq && sudo sysctl -w net.ipv4.tcp_congestion_control=bbr',
      cmp: [{ aspect: 'Tín hiệu tắc nghẽn', optionA: 'Reno / CUBIC: Coi Mất gói (Packet Loss) là tắc nghẽn -> dễ gây Bufferbloat', optionB: 'BBR: Đo RTT tăng & Throughput bão hòa để tránh tràn queue trước khi mất gói' }],
      apps: ['YouTube/Google tăng mạnh throughput và giảm latency bufferbloat trên mạng di động không ổn định bằng BBR.'],
      troubleshoot: ['Trên mạng Wi-Fi/4G thỉnh thoảng rớt 1% gói ngẫu nhiên (không phải do nghẽn!), thuật toán CUBIC tưởng nhầm nghẽn nặng nên bóp nghẹt tốc độ xuống rất thấp — BBR khắc phục rất tốt tình trạng này.'],
      sec: ['**TCP Slow Start Restart** sau thời gian idle có thể làm request tiếp theo bị chậm đột ngột trên kết nối Keep-Alive dài nếu không tắt `tcp_slow_start_after_idle`.'],
      qa: [{ question: 'Tại sao mở một kết nối TCP mới tải file 5MB lại chậm ở giây đầu rồi mới nhanh dần (Slow Start), và bật Keep-Alive lại giúp API nhanh hơn?', answer: 'Kết nối TCP mới bắt đầu với `cwnd` nhỏ (10 MSS) và cần vài vòng RTT để tăng dần lên đạt tối đa băng thông; dùng lại kết nối cũ qua Keep-Alive bỏ qua cả bắt tay lẫn giai đoạn Slow Start ban đầu.' }],
      ex: { prompt: 'Kiểm tra xem `Initial Congestion Window` (`initcwnd`) và thuật toán `tcp_congestion_control` hiện tại trên máy Linux của bạn là gì.', solutionHint: 'Dùng `ip route` (tìm `initcwnd`) và `sysctl net.ipv4.tcp_available_congestion_control`.' },
