      defs: [{ term: 'Connection Migration (QUIC)', meaning: 'TCP định danh kết nối bằng 4-tuple IP:Port nên khi điện thoại đổi từ Wi-Fi sang 4G, IP đổi -> rớt mọi kết nối TCP! QUIC dùng `Connection ID` 64-bit độc lập với IP nên chuyển mạng mượt mà không rớt cuộc gọi/tải file.' }],
      theory: '### Tiết kiệm bắt tay với QUIC\n- **TCP + TLS 1.2**: 1 RTT TCP + 2 RTT TLS = **3 RTT** mới gửi được HTTP.\n- **TCP + TLS 1.3**: 1 RTT TCP + 1 RTT TLS = **2 RTT**.\n- **QUIC (HTTP/3)**: Gộp Transport + TLS 1.3 -> **1 RTT** cho kết nối mới, và **0-RTT** khi kết nối lại!',
