      theory: '### WebSocket vs Server-Sent Events (SSE) vs Long Polling\n- **Long Polling**: Client gửi HTTP chờ mãi tới khi có data -> đóng -> mở lại (tốn header).\n- **SSE (`text/event-stream`)**: Chạy thuần HTTP/1.1-2, **1 chiều (Server → Client)**, tự reconnect sẵn — cực hợp cho **AI LLM Token Streaming (ChatGPT/Claude)**!\n- **WebSocket (`ws://`/`wss://`)**: **2 chiều Full-Duplex** tốc độ cực thấp (<2–6 bytes framing overhead), lý tưởng cho Game, Trading Board, Collaborative Editor.',
