      sec: ['Dùng SSH Ed25519 key + tắt Password Auth (`PasswordAuthentication no`); với WebSocket luôn dùng `wss://` (TLS) và kiểm tra `Origin` header chống Cross-Site WebSocket Hijacking!'],
