      pktSummary: 'TLS 1.3 finishes handshake in 1 RTT and mandates Forward Secrecy',
      pktLayers: [{ layerName: 'SNI Plaintext Caveat', detail: 'Trong ClientHello chuẩn, tên miền SNI vẫn lộ dạng chữ rõ -> ECH (Encrypted Client Hello) đang giải quyết điều này' }],
      cmdLang: 'bash',
