      sec: ['**mTLS (Mutual TLS)** yêu cầu CẢ Server lẫn Client đều trình bày và xác thực chứng chỉ của nhau — tiêu chuẩn vàng cho Zero-Trust giao tiếp giữa các Microservices Backend!'],
      qa: [{ question: 'Tại sao HTTPS không mã hóa toàn bộ dữ liệu bằng khóa bất đối xứng RSA luôn cho gọn mà phải sinh khóa đối xứng ở bước bắt tay?', answer: 'Mã hóa bất đối xứng (RSA/ECC) tốn tài nguyên CPU tính toán lũy thừa số lớn chậm hơn hàng trăm đến hàng nghìn lần so với mã hóa đối xứng (AES-GCM có tập lệnh phần cứng AES-NI). Vì vậy TLS chỉ dùng bất đối xứng lúc bắt tay để xác thực danh tính và thỏa thuận khóa phiên đối xứng (ECDHE), sau đó mã hóa luồng dữ liệu lớn bằng đối xứng.' }],
      ex: { prompt: 'Chạy lệnh `openssl s_client -connect google.com:443 -servername google.com < /dev/null` và tìm dòng `Protocol`, `Cipher` và `Verify return code`.', solutionHint: 'Verify return code: 0 (ok), Protocol: TLSv1.3.' },
