      theory: '### Quy tắc vàng đọc báo cáo `mtr` / `traceroute`!\nNếu tại **Hop 5** thấy `Loss = 60%`, nhưng từ **Hop 6 cho tới Đích (Hop 12)** có `Loss = 0%` → **Hop 5 KHÔNG HỀ BỊ LỖI MẠNG**!\nĐơn giản là Router ở Hop 5 cấu hình ưu tiên forward gói đi tiếp bằng chip ASIC nhưng giới hạn tốc độ CPU trả lời ICMP Time Exceeded cho bạn (Control Plane rate-limit). Chỉ khi Packet Loss bắt đầu xuất hiện từ Hop K và **kéo dài tới tận đích cuối** thì Hop K mới thực sự bị nghẽn/rớt gói!',
