      apps: ['Gửi báo cáo `mtr` hai chiều (Client -> Server và Server -> Client vì đường đi và đường về trên BGP thường bất đối xứng!) khi mở ticket với nhà cung cấp Cloud/ISP.'],
      troubleshoot: ['Thấy `* * *` tại một vài hop rồi phía sau hiện lại bình thường -> Router đó chặn/rate-limit trả ICMP, đừng hoảng hốt!'],
      sec: ['Một số hệ thống nhạy cảm chặn hoàn toàn ICMP Echo ở biên nên dùng `mtr -T -P 443` (TCP SYN traceroute) để test đúng đường đi của HTTPS.'],
      qa: [{ question: 'Trong kết quả `mtr` qua 10 hop, thấy hop số 4 báo `Loss% = 70%` nhưng các hop từ 5 đến 10 đều `0% Loss`. Điều này có nghĩa là gì?', answer: 'Hop số 4 KHÔNG bị mất gói dữ liệu chuyển tiếp! Nó chỉ đang rate-limit việc CPU tạo bản tin phản hồi ICMP Time Exceeded cho các gói thăm dò TTL=4, trong khi vẫn forward hoàn hảo toàn bộ gói có TTL lớn hơn đi tới đích.' }],
