      concepts: ['`ss -tulnp` (Socket đang nghe & PID tiến trình)', '`ss -tni` (Xem chi tiết `cwnd`, `rtt`, `retrans` của từng kết nối TCP!)', '`ip route get <IP>` (Hỏi Kernel gói tới IP này sẽ đi qua cổng nào)', '`nstat` / `netstat -s` (Đếm tràn Listen Overflow / SYN Drops)'],
      defs: [{ term: 'Accept Queue Overflow (`ListenOverflows`)', meaning: 'Khi ứng dụng gọi `accept()` không kịp lúc traffic tăng đột biến làm đầy Accept Queue, Kernel buộc phải drop gói ACK cuối (hoặc gửi RST) khiến Client dính lỗi Connection Reset/Timeout dù CPU chưa hẳn 100%!' }],
      theory: '### Bắt bệnh nhanh Server Backend chậm bất thường bằng `ss`\n- Chạy `ss -tln` nhìn cột `Recv-Q` và `Send-Q` trên dòng `LISTEN`:\n  - `Recv-Q`: số kết nối đang kẹt chờ App gọi `accept()`.\n  - `Send-Q`: kích thước tối đa Accept Queue (`somaxconn`).\n  - Nếu `Recv-Q == Send-Q` -> **Server App đã bị nghẽn không kịp accept kết nối mới!**',
      steps: ['Kiểm tra Link & IP: `ip -br a`.', 'Kiểm tra Routing thực tế: `ip route get <dst>`.', 'Kiểm tra Port & Process: `ss -tulnp`.', 'Kiểm tra tràn hàng đợi & Retransmits: `ss -tni` và `nstat -az TcpExtListenOverflows`.'],
