      cmp: [{ aspect: 'Công cụ hệ thống', optionA: 'netstat / ifconfig (cũ): Chậm khi server có hàng chục nghìn socket', optionB: 'ss / ip (iproute2 mới): Nhanh, hiện chi tiết cwnd, rtt, retransmits, process' }],
      apps: ['Debug lỗi 502/504 Gateway Timeout giữa Nginx và Java/Go/Node backend.'],
      troubleshoot: ['App báo "listening on 127.0.0.1:8080" -> nhìn `ss -tln` thấy `Local Address = 127.0.0.1:8080` thay vì `0.0.0.0:8080` -> không bao giờ nhận được kết nối từ máy khác hay Docker host trừ khi đổi bind sang `0.0.0.0`!'],
      sec: ['Kiểm tra `ss -tulnp` định kỳ để phát hiện port lạ mở lén trên `0.0.0.0` (vd: Redis/MongoDB quên khóa bind localhost!).'],
      qa: [{ question: 'Khi chạy `ss -tln` trên một server đang tải cao, cột `Recv-Q` và `Send-Q` trên dòng trạng thái `LISTEN` có ý nghĩa gì?', answer: 'Đối với socket `LISTEN`, `Send-Q` là kích thước tối đa của Accept Queue (`min(backlog, somaxconn)`), còn `Recv-Q` là số kết nối đã hoàn tất bắt tay 3 bước đang nằm chờ ứng dụng gọi `accept()`. Nếu `Recv-Q` tiến sát hoặc bằng `Send-Q` chứng tỏ ứng dụng không rút kịp kết nối mới.' }],
      ex: { prompt: 'Chạy `ss -tln` và giải thích sự khác nhau giữa service bind vào `127.0.0.1:PORT` vs `0.0.0.0:PORT` vs `[::]:PORT`.', solutionHint: '`127.0.0.1` chỉ nhận kết nối nội bộ trên loopback; `0.0.0.0` nghe mọi interface IPv4; `[::]` thường nghe mọi interface IPv6 (và cả IPv4 nếu `IPV6_V6ONLY=0`).' },
