      theory: '### Bộ lọc Wireshark "cứu mạng" khi debug sự cố\n- `tcp.analysis.flags` -> Tìm mọi bất thường (Retransmission, ZeroWindow, Out-Of-Order, Dup ACK).\n- `tcp.flags.reset == 1` -> Tìm các kết nối bị ngắt cưỡng bức bằng TCP RST.\n- `tls.handshake.type == 1` -> Xem SNI domain trong gói `ClientHello` ngay cả khi TLS đang mã hóa!',
