      overview: 'Lập trình viên mới viết Socket hay mắc đúng một lỗi kinh điển: gọi `send()` 2 lần cho 2 thông điệp nhưng bên nhận gọi `recv()` 1 lần lại nhận gộp cả 2 (hoặc bị cắt làm nửa)!',
