      defs: [{ term: 'Length-Prefixed Framing', meaning: 'Đặt 4 bytes độ dài $N$ ngay trước mỗi thông điệp nhị phân: bên nhận đọc đủ 4 byte lấy $N$, rồi lặp đọc cho tới khi gom đủ chính xác $N$ byte mới xử lý.' }],
      theory: '### Tại sao `recv(buf, 1024)` có thể chỉ trả về 17 bytes hoặc trả về 2 message dính nhau?\nVì TCP chỉ coi dữ liệu như **một dòng ống nước byte liên tục**! Tùy thuộc vào MSS, Nagle’s Algorithm và tốc độ đọc, Kernel có thể tách 1 `send()` lớn thành nhiều đoạn hoặc gộp 3 `send()` nhỏ thành 1 gói.',
      steps: ['Chọn chiến lược Framing (HTTP dùng `\\r\\n` + `Content-Length`; gRPC/Redis/Kafka dùng Length-Prefix / Binary Header).', 'Viết hàm `readExactly(n)` lặp cho tới khi đủ số byte hoặc gặp EOF (`0`).', 'Xử lý ngắt kết nối gọn gàng và đặt Read/Write Deadlines.'],
