      cmp: [{ aspect: 'Chiến lược Framing', optionA: 'Delimiter (`\\n` / `\\r\\n`): Dễ debug bằng chữ (SMTP, HTTP/1.1), phải escape ký tự xuống dòng trong data nhị phân', optionB: 'Length-Prefix (`!I`): Hỗ trợ payload nhị phân tùy ý (Protobuf/Ảnh/Video) tốc độ O(1)' }],
