      sec: ['Luôn kiểm tra giới hạn `max_frame_size` trước khi `malloc(msg_len)` từ 4 byte length do client gửi lên — nếu không kẻ xấu gửi `length = 2GB` làm sập server (Out Of Memory DoS)!'],
