      theory: '### Tại sao Unconnected UDP không báo lỗi khi cổng đích đang đóng?\nNếu bạn gọi `sendto()` bằng UDP socket chưa `connect()`, Router/Đích gửi về ICMP Port Unreachable, nhưng Kernel thường không biết giao lỗi bất đồng bộ đó về cho lệnh nào -> app không nhận được `ECONNREFUSED` trừ khi gọi `connect()` trên UDP socket!',
