      theory: '### Tại sao VPN "lâu đài & hào nước" (Castle-and-Moat) đang lỗi thời?\nMột khi lọt qua được cổng VPN vào mạng nội bộ, kẻ tấn công có thể quét toàn bộ dải IP bên trong! **Zero Trust (ZTNA / BeyondCorp)** không tin cậy bất kỳ gói tin nào chỉ vì nó nằm cùng IP nội bộ — mọi kết nối đều phải xác thực danh tính người dùng/service + chứng chỉ thiết bị (mTLS) ở từng ứng dụng cụ thể.',
      steps: ['Xác thực danh tính thiết bị & người dùng tại Control Plane.', 'Thiết lập kết nối trực tiếp Peer-to-Peer hoặc qua Edge Proxy gần nhất.', 'Cấp quyền truy cập theo từng microservice/port thay vì mở cả subnet `/16`.'],
