      sec: ['Rotate khóa WireGuard/VPN và thu hồi quyền ngay khi nhân sự nghỉ việc hoặc mất thiết bị qua tích hợp SSO/IdP (Okta/Google Workspace).'],
      qa: [{ question: 'Kiến trúc Zero-Trust Network Access (ZTNA) khắc phục điểm yếu nào của mô hình VPN doanh nghiệp truyền thống?', answer: 'VPN truyền thống đặt niềm tin theo vị trí mạng ("cứ vào được mạng nội bộ là tin cậy" nên dễ bị di chuyển ngang Lateral Movement) và thường dồn traffic qua 1 Hub gây chậm; ZTNA xác thực từng phiên theo danh tính + tình trạng thiết bị (device posture) ở mức từng ứng dụng bất kể người dùng ngồi ở đâu.' }],
