      defs: [{ term: 'Origin Shield', meaning: 'Một tầng Cache đệm tập trung đặt ngay trước Origin Server để hàng trăm Edge PoP trên thế giới khi bị Cache Miss đều hỏi qua Shield thay vì tất cả cùng đồng loạt đánh sập Origin (Thundering Herd).' }],
      theory: '### Tại sao CDN không chỉ dùng cho Ảnh tĩnh mà còn tăng tốc API Động?\n1. **TCP/TLS Termination tại Edge**: Người dùng ở Việt Nam bắt tay TCP + TLS với PoP ngay tại HCM/Hà Nội chỉ mất **5–15ms RTT** (thay vì 220ms sang Mỹ!).\n2. **Persistent Connections tới Origin**: CDN giữ sẵn các kết nối TCP ấm, tối ưu đường đi (Argo Smart Routing) về Origin!',
