      sec: ['**Cache Poisoning**: Lợi dụng một HTTP Header không nằm trong Cache Key (như `X-Forwarded-Host`) để tiêm mã XSS vào bản cache dùng chung cho hàng triệu người -> luôn kiểm soát chặt Cache Key và chỉ bật public cache khi an toàn!'],
