      concepts: ['Power of Two Choices (Giảm Herd Effect trên distributed LBs)', 'Maglev Consistent Hashing (Google)', 'Retry Amplification Storms & Exponential Backoff + Jitter', 'Happy Eyeballs (RFC 8305 — đua kết nối IPv6 vs IPv4)'],
      defs: [{ term: 'Power of Two Choices', meaning: 'Thay vì hàng chục Load Balancer độc lập đều chọn 1 node nhàn nhất (tạo đám đông ập vào node đó cùng lúc!), mỗi LB bốc ngẫu nhiên 2 backend rồi chọn cái tốt hơn trong 2 cái đó — hiệu quả vượt trội cho hệ phân tán!' }],
      theory: '### Thảm họa Retry Storm\nNếu chuỗi A → B → C mỗi tầng đều cài đặt `retry = 3`: khi C chỉ chớm chậm nhẹ, B thử lại 3 lần và A thử lại 3 lần -> lượng tải bắn xuống C tăng lên **$3 \\times 3 = 9$ lần**, biến một trục trặc nhỏ thành sập toàn diện! Giải pháp: **Retry Budget (chỉ retry tối đa 10–20% tổng traffic)**, **Circuit Breaker** và **Jitter**.',
      steps: ['Phát hiện kết nối IPv4/IPv6 bằng Happy Eyeballs (ưu tiên IPv6, fallback IPv4 sau 250ms nếu kẹt).', 'Phân tải qua Consistent Hashing hoặc Power of Two Choices.', 'Áp dụng Outlier Detection (Circuit Breaker) rút node lỗi tạm thời và giới hạn Retry Budget.'],
