      layer: 'Distributed Traffic Engineering',
      ports: 'L4 Maglev / L7 Envoy xDS',
      fields: 'Circuit Breaker Thresholds | Outlier Ejection | Jitter Backoff',
      diag: ['Resilient Traffic Mesh', 'Client (Happy Eyeballs v6/v4)', 'L4 Maglev -> L7 Envoy (2-Choices)', 'Circuit Breaker + Retry Budget -> Pods'],
      pktSummary: 'Dual-stack clients race IPv6 and IPv4 connections with a 250ms head start for IPv6',
