      cmp: [{ aspect: 'Chiến lược Load Balancing phân tán', optionA: 'Naive Least-Conn ở nhiều LB độc lập: Mọi LB cùng thấy Node X vừa rảnh -> dồn hết vào X', optionB: 'Power of Two Choices (Nginx/Envoy): Bốc ngẫu nhiên 2 node, chọn node ít tải hơn' }],
      apps: ['Envoy Proxy, HAProxy, Google Maglev L4 LB, AWS SDK Full Jitter Retry.'],
