      theory: '### Tối ưu Chi phí & Bảo mật Cloud bằng VPC Endpoint (PrivateLink)\nNếu các pod trong Private Subnet gọi AWS S3 hoặc DynamoDB qua **NAT Gateway**, bạn vừa bị tính phí truyền dữ liệu qua NAT Gateway ($0.045/GB), vừa đi vòng ra cửa Internet! Gắn **Gateway VPC Endpoint** giúp traffic đi nội bộ thẳng từ Private Subnet tới S3 miễn phí và an toàn tuyệt đối.',
