      theory: '### Tại sao Root Domain (`example.com`) không đặt CNAME được nhưng AWS Route53/Cloudflare lại làm được?\nTheo chuẩn RFC DNS, Apex Domain bắt buộc có record `NS` và `SOA`, không được phép đặt `CNAME`. Cloud DNS giải quyết bằng **ALIAS Record / CNAME Flattening**: ở phía Name Server tự động phân giải đích Load Balancer thành các bản ghi `A` động rồi trả về cho Client!',
