      theory: '### Tại sao Discovery chỉ dùng DNS truyền thống có thể không đủ khi scale lớn?\n1. DNS chuẩn không gắn sẵn port động tốt (phải dùng **DNS SRV records**).\n2. Nhiều runtime/client cache DNS bỏ qua TTL -> khi 1 Pod bị kill, client vẫn bắn traffic vào IP Pod đã chết thêm vài chục giây!\nDo đó **Kubernetes Service (VIP + eBPF/IPVS)** hoặc **Envoy xDS (EDS)** đẩy danh sách Endpoint sống trực tiếp qua gRPC streaming tức thời!',
