      sec: ['Bảo vệ Service Registry (`etcd`/`Consul`) bằng mTLS & RBAC nghiêm ngặt — ai giả mạo đăng ký được vào Registry có thể hút toàn bộ traffic của một microservice!'],
      qa: [{ question: 'Trong Kubernetes, hiện tượng `ndots:5` làm bùng nổ lượng truy vấn DNS nội bộ xảy ra như thế nào và khắc phục ra sao?', answer: 'Mặc định `/etc/resolv.conf` trong Pod đặt `ndots:5`, nghĩa là bất kỳ tên miền nào có ít hơn 5 dấu chấm (như `google.com` hay `s3.amazonaws.com`) sẽ bị coi là tên tương đối và thử nối thêm hàng loạt search domains (`.svc.cluster.local`, `.cluster.local`...) tạo ra tới 4–8 truy vấn DNS thừa (cả A & AAAA) trước khi thử tên tuyệt đối; khắc phục bằng hạ `ndots:2` hoặc dùng FQDN có dấu chấm cuối.' }],
