      overview: 'Mỗi Container nhìn thấy một card mạng `eth0` và bảng định tuyến riêng nhờ Linux Network Namespace; tất cả sự kết nối ra ngoài đều đi qua những khối ghép Linux cơ bản: `veth pair`, Linux Bridge và VXLAN.',
      concepts: ['Network Namespace (`netns`)', '`veth pair` (Cặp dây cáp ảo nối 2 Namespace)', 'Linux Bridge (`docker0` / `cni0`)', 'Cross-Host Overlay (VXLAN UDP 4789) vs BGP Direct Routing (Calico)'],
      defs: [{ term: 'veth pair (Virtual Ethernet Pair)', meaning: 'Hai giao diện mạng ảo sinh ra thành một cặp nối thẳng với nhau như hai đầu của một sợi cáp Ethernet: gói tin đẩy vào đầu A ngay lập tức xuất hiện ở đầu B trong một Network Namespace khác!' }],
      theory: '### Hành trình gói tin từ Container 1 sang Container 2 ở 2 Server khác nhau\n1. Gói rời `eth0` trong `netns` Container 1 đi qua đầu kia của cặp `veth` vào Root Host Namespace.\n2. Đi qua Bridge (`cni0`) hoặc eBPF hook kiểm tra đích thuộc Node khác.\n3. Với **VXLAN Overlay**: Host 1 bọc nguyên Ethernet Frame của Container vào gói UDP port `4789` (Outer IP = Host 1 -> Host 2), gửi qua mạng thật.\n4. Host 2 bóc UDP/VXLAN, đẩy frame vào `veth` của Container 2!',
      steps: ['Tạo Network Namespace mới cho Container/Pod.', 'Tạo cặp `veth`, ném 1 đầu vào container đổi tên thành `eth0`, đầu kia cắm vào Bridge/eBPF trên Host.', 'Gán IP từ dải Pod CIDR (qua CNI plugin IPAM).', 'Thiết lập định tuyến liên Node (BGP hoặc VXLAN encapsulation).'],
      rfc: 'CNI Spec · RFC 7348 (VXLAN)',
