      diag: ['Container veth & VXLAN', 'Pod1 (eth0) ==veth==> Host1 Bridge/eBPF', 'VXLAN UDP/4789 across Physical Net', 'Host2 ==veth==> Pod2 (eth0)'],
      pktSummary: 'VXLAN adds ~50 bytes overhead; remember to adjust Pod MTU (e.g. 1450B)!',
      pktLayers: [{ layerName: 'Encapsulation', detail: 'Outer Eth + Outer IP + Outer UDP (4789) + 8B VXLAN Header + Inner Eth + Inner IP + Payload' }],
      cmdLang: 'bash',
      cmdTitle: 'Liệt kê Network Namespaces và cặp veth trên máy chủ Linux chạy Docker/K8s',
      cmd: 'ip netns list\nip link show type veth',
      cmp: [{ aspect: 'Mạng giữa các Node K8s', optionA: 'Overlay (Flannel VXLAN): Chạy được trên mọi hạ tầng L3 không cần sửa router thật, nhưng tốn ~50B overhead & CPU encap', optionB: 'Underlay / Direct Routing (Calico BGP / AWS VPC CNI): Không tốn encap overhead, tốc độ gốc wire-speed' }],
