      sec: ['Vô hiệu hóa ICC (Inter-Container Communication) trên Docker bridge mặc định hoặc dùng Kubernetes **NetworkPolicy** (L3/L4) để mặc định cấm các Pod khác namespace nói chuyện tự do với Database!'],
      qa: [{ question: 'Cặp thiết bị `veth pair` đóng vai trò gì trong mạng Container, và tại sao dùng Overlay VXLAN lại phải giảm MTU bên trong Container từ 1500 xuống 1450?', answer: '`veth pair` đóng vai trò sợi dây nối ảo xuyên biên giới giữa Network Namespace cô lập của Container và Root Namespace của Host OS. Khi dùng VXLAN bọc thêm ~50 bytes Outer IP/UDP/VXLAN header lên mỗi gói tin, nếu giữ Payload bên trong 1500 bytes thì tổng gói gửi ra card mạng thật thành 1550 bytes bị rớt/phân mảnh, nên phải hạ MTU của Pod xuống 1450 bytes.' }],
      ex: { prompt: 'Kiểm tra MTU trên interface `eth0` và `docker0` (hoặc `cni0`) trên máy Linux.', solutionHint: 'Chạy `ip link | grep -E "mtu|docker0|veth"` để quan sát cấu trúc liên kết.' },
