      qa: [{ question: 'Tại sao nếu bạn SSH vào một Kubernetes Worker Node và gõ `ping <ClusterIP>` thì thường không ping được, dù các Pod bên trong vẫn gọi được HTTP tới `<ClusterIP>` đó?', answer: 'Vì `ClusterIP` là một Virtual IP thuần túy tồn tại dưới dạng luật DNAT trong Kernel (`iptables` / `IPVS` / `eBPF`) chứ KHÔNG gắn vào bất kỳ interface mạng vật lý nào, và các luật DNAT đó thường chỉ xử lý các cổng TCP/UDP cụ thể của Service chứ không trả lời gói ICMP Echo!' }],
      ex: { prompt: 'Giải thích vai trò của `pause` container trong mỗi Kubernetes Pod đối với hạ tầng mạng.', solutionHint: 'Container `pause` được khởi tạo đầu tiên để giữ cố định Linux Network Namespace (`eth0`, IP của Pod); các app container & sidecar sau đó join vào cùng `netns` đó để dùng chung IP và `localhost`.' },
